var deal = $('Fetch Deal from Convex').first().json.data;
var source = $('Fetch Buyers from InsulaCRM').first().json;
var buyers = source.data || source || [];
var priorityBuyers = $('Check Priority Queue').first().json.data || [];
var protectedStatuses = ['human hand','hot lead','hot','warm lead','interested','not interested','dnc','dead','vetted buyer','vip'];
var priorityBuyerIds = priorityBuyers.map(function(p){ return p.buyerId; });
var excludedBuyerIds = deal.excludedBuyerIds || [];
var matchedBuyers = [];

for (var i=0;i<buyers.length;i++) {
  var buyer=buyers[i];
  var statusLabel=(buyer.status || buyer.buyer_tier || 'warm').toLowerCase().trim();
  if (protectedStatuses.indexOf(statusLabel)!==-1) continue;
  var buyerId=buyer.id || buyer.external_id;
  if (excludedBuyerIds.indexOf(buyerId)!==-1) continue;

  var markets=[].concat(buyer.preferred_zip_codes || [], buyer.preferred_states || []).map(function(v){ return String(v).toLowerCase().trim(); });
  var priceMin=Number(buyer.min_purchase_price || 0);
  var priceMax=Number(buyer.max_purchase_price || 999999999);
  var strategies=buyer.preferred_strategies || [];
  var conditions=buyer.preferred_conditions || ['Light','Medium','Heavy'];
  var propertyTypes=buyer.preferred_property_types || ['SFR','Duplex','Multi'];
  var phone=buyer.phone;
  if(!phone) continue;

  var dealZip=String(deal.zip||'').toLowerCase();
  var dealState=String(deal.state||'').toLowerCase();
  var dealCity=String(deal.city||'').toLowerCase();
  var marketMatch=false, marketMatchScore=0;
  for(var m=0;m<markets.length;m++){
    if(markets[m]===dealZip){marketMatch=true;marketMatchScore=1;break;}
    if(markets[m]===dealState){marketMatch=true;marketMatchScore=0.8;}
    if(markets[m]===dealCity){marketMatch=true;marketMatchScore=0.7;}
  }
  if(!marketMatch) continue;

  var priceBuffer=(priceMax-priceMin)*0.1;
  if(deal.askingPrice < priceMin-priceBuffer || deal.askingPrice > priceMax+priceBuffer) continue;
  var priceMatchScore=(deal.askingPrice>=priceMin && deal.askingPrice<=priceMax)?1:0.5;
  if(conditions.length && conditions.indexOf(deal.repairScope)===-1) continue;
  var strategyMatchScore=strategies.length ? (strategies.indexOf(deal.bestStrategy)!==-1?1:0.3) : 0.5;
  var propertyTypeMatchScore=propertyTypes.indexOf(deal.propertyType)!==-1?1:0.2;
  var tier=buyer.buyer_tier || 'warm';
  var tierBonusMap={'hot':1,'warm':0.6,'cold':0.3};
  var tierBonus=tierBonusMap[tier]||0.5;
  var priorityBonus=priorityBuyerIds.indexOf(buyerId)!==-1?0.2:0;

  var matchScore=marketMatchScore*0.25+priceMatchScore*0.25+strategyMatchScore*0.15+propertyTypeMatchScore*0.10+tierBonus*0.10+priorityBonus;
  matchedBuyers.push({
    closeLeadId: buyer.external_source==='close' ? buyer.external_id : null,
    convexBuyerId: buyer.external_id || buyer.id,
    insulaBuyerId: buyer.id,
    name: buyer.full_name || ((buyer.first_name||'')+' '+(buyer.last_name||'')).trim(),
    phone: phone,
    tier: tier,
    matchScore: Math.round(matchScore*100)/100,
    isPriority: priorityBuyers.indexOf(buyerId)!==-1
  });
}
var tierOrder={'hot':0,'warm':1,'cold':2};
matchedBuyers.sort(function(a,b){
  if(a.isPriority!==b.isPriority) return a.isPriority?-1:1;
  if(tierOrder[a.tier]!==tierOrder[b.tier]) return tierOrder[a.tier]-tierOrder[b.tier];
  return b.matchScore-a.matchScore;
});
return {json:{deal:deal,matchedBuyers:matchedBuyers,totalMatched:matchedBuyers.length}};

var data = $input.first().json;
var buyers = data.matchedBuyers;

var limits = { 'hot': 5, 'warm': 15, 'cold': 30 };
var counts = { 'hot': 0, 'warm': 0, 'cold': 0 };
var selected = [];
var disqualified = { total: 0, hot_limit: 0, warm_limit: 0, cold_limit: 0 };

for (var i = 0; i < buyers.length; i++) {
  var buyer = buyers[i];
  var tier = buyer.tier;

  if (counts[tier] < limits[tier]) {
    counts[tier]++;
    selected.push(buyer);
  } else {
    disqualified.total++;
    disqualified[tier + '_limit']++;
  }
}

return { json: { deal: data.deal, selectedBuyers: selected, counts: counts, disqualified: disqualified } };

var data = $input.first().json;
var buyers = data.selectedBuyers;
var deal = data.deal;
var counts = data.counts;
var disqualified = data.disqualified;

var results = [];
for (var i = 0; i < buyers.length; i++) {
  var buyer = buyers[i];

  var templates = {
    'hot': { id: 'P1', text: 'Got a deal in ' + deal.city + ' — you get first look. Interested?' },
    'warm': { id: 'P2', text: 'Got a deal in ' + deal.city + '. Interested?' },
    'cold': { id: 'P3', text: 'Deal in ' + deal.city + '. Want the details?' }
  };

  var template;
  if (buyer.isPriority) {
    template = { id: 'PRIORITY', text: 'Got another one in ' + deal.city + ' — you get first look. Interested?' };
  } else {
    template = templates[buyer.tier] || templates['warm'];
  }

  results.push({
    json: {
      buyer: buyer,
      deal: deal,
      templateId: template.id,
      smsText: template.text,
      counts: counts,
      disqualified: disqualified
    }
  });
}

return results;
